def transforms(shape):
 out=[]
 for k in range(4):
  for refl in [False,True]:
   pts=[]
   for r,c in shape:
    x,y=r,c
    if refl:y=-y
    for _ in range(k):x,y=y,-x
    pts.append((x,y))
   minr=min(x for x,y in pts); minc=min(y for x,y in pts)
   norm=frozenset((x-minr,y-minc) for x,y in pts)
   if norm not in out:out.append(norm)
 return out

def occurrences_union(G, shape, color=0):
 h,w=len(G),len(G[0]); occ=[]; union=set()
 for sh in transforms(shape):
  hh=max(r for r,c in sh)+1; ww=max(c for r,c in sh)+1
  for r in range(h-hh+1):
   for c in range(w-ww+1):
    cells={(r+a,c+b) for a,b in sh}
    if all(G[x][y]==color for x,y in cells):
     occ.append(cells);union|=cells
 return occ,union
